// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, address actor, uint256 minSum) public {
        vm.assume(amount1 > 0);
        vm.assume(amount2 > 0);
        vm.assume(minSum > 0);
        vm.assume(amount2 <= amount1);
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        // ensure sum overflows (amount1 + amount2 > type(uint256).max)
        vm.assume(amount1 > type(uint256).max - amount2);

        // initialize the contract
        c.SetMinSum(minSum);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();

        vm.deal(actor, amount1 + amount2);
        vm.startPrank(actor);
        // first deposit: normal
        c.Deposit{value: amount1}();
        // second deposit: triggers overflow in the buggy version
        c.Deposit{value: amount2}();
        vm.stopPrank();

        // try to collect amount2, which should succeed in the reference (balance is amount1+amount2, no overflow)
        // but in the buggy version balance overflowed, so collect will revert.
        uint256 savedBal = c.balances(actor);
        if (savedBal >= minSum && savedBal >= amount2) {
            vm.prank(actor);
            bool ok = true;
            try c.Collect(amount2) {} catch { ok = false; }
            assertTrue(ok);
        } else {
            // we arranged amounts so balance should be >= minSum and >= amount2, so this branch is unreachable under the invariant
            assertTrue(false);
        }
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr,uint _val,string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

