pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, address sender) public {
        vm.assume(sender != address(0));
        vm.assume(depositAmount <= type(uint256).max - c.balances(sender));

        uint256 contractBalanceBefore = address(c).balance;
        uint256 totalBalancesBefore = 0;
        // We can't iterate all addresses, so we track known sender balance
        uint256 senderBalanceBefore = c.balances(sender);

        vm.deal(sender, depositAmount);
        vm.prank(sender);
        c.Deposit{value: depositAmount}();

        uint256 contractBalanceAfter = address(c).balance;
        uint256 senderBalanceAfter = c.balances(sender);

        // Invariant: contract balance must equal sum of all individual balances.
        // Since we only know sender's balance changed, we check that the contract balance
        // increased exactly by the deposit amount, which must equal the sender's balance increase.
        // This holds if sender's balance didn't overflow.
        assertTrue(contractBalanceAfter - contractBalanceBefore == senderBalanceAfter - senderBalanceBefore);
        assertTrue(senderBalanceAfter - senderBalanceBefore == depositAmount);
    }
}

