pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address depositor1, uint96 deposit1, address depositor2, uint96 deposit2) public {
        // Ensure distinct addresses and non-zero deposits for meaningful interaction
        vm.assume(depositor1 != address(0));
        vm.assume(depositor2 != address(0));
        vm.assume(depositor1 != depositor2);
        vm.assume(deposit1 > 0);
        vm.assume(deposit2 > 0);

        // Initialize the contract
        c.Initialized();

        // First deposit by depositor1
        vm.deal(depositor1, deposit1);
        vm.prank(depositor1);
        c.Deposit{value: deposit1}();

        // Second deposit by depositor2
        vm.deal(depositor2, deposit2);
        vm.prank(depositor2);
        c.Deposit{value: deposit2}();

        // General rule: after all deposits, every depositor's balance must be at least the ETH they individually sent.
        // For the reference contract, this holds for ALL inputs. For the mutant, depositor1's balance is overwritten
        // to 0 by the new `balances[msg.sender] = msg.value` in Deposit when depositor2 deposits, violating the rule.
        assertTrue(c.balances(depositor1) >= deposit1 && c.balances(depositor2) >= deposit2);
    }
}

