pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address depositor1, uint96 amount1, address depositor2, uint96 amount2) public {
        // Restrict depositors to be distinct EOA-like addresses that can receive call refunds
        vm.assume(depositor1 != address(0) && depositor2 != address(0));
        vm.assume(depositor1 != depositor2);
        vm.assume(uint160(depositor1) > 0xff && uint160(depositor2) > 0xff);
        // Restrict amounts to avoid overflow in C's require and allow two deposits to fit in EVM balance
        vm.assume(amount1 > 0 && amount1 <= type(uint96).max / 2);
        vm.assume(amount2 > 0 && amount2 <= type(uint96).max - amount1);

        // Initialize C and set a high MinSum so Collect does not interfere
        vm.startPrank(address(this));
        c.Initialized();
        c.SetMinSum(type(uint).max);
        vm.stopPrank();

        // First deposit
        vm.deal(depositor1, amount1);
        vm.prank(depositor1);
        c.Deposit{value: amount1}();

        // Second deposit by different depositor
        vm.deal(depositor2, amount2);
        vm.prank(depositor2);
        c.Deposit{value: amount2}();

        // Assert: sum of balances equals contract balance (total deposited ether)
        uint256 sumBalances = c.balances(depositor1) + c.balances(depositor2);
        uint256 totalDeposits = amount1 + amount2;
        assertTrue(sumBalances == totalDeposits);
    }
}

