pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reverter reverter;

    function setUp() public {
        c = new C();
        reverter = new Reverter();
    }

    function testFuzz_property(uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        // Bound to reasonable ranges to avoid overflow/underflow issues while keeping domain wide
        minSum = bound(minSum, 1, type(uint128).max);
        depositAmount = bound(depositAmount, minSum + 1, type(uint128).max);
        collectAmount = bound(collectAmount, 1, minSum);

        // Set up the adversarial callee: the reverter contract will fail on Collect
        // Initialize the contract
        c.SetMinSum(0);
        c.SetLogFile(address(reverter));
        c.Initialized();

        // Set MinSum through the reverter's context to test the property
        vm.prank(address(reverter));
        c.SetMinSum(minSum);

        // Verify that MinSum was correctly set
        uint256 minSumAfterSet = c.MinSum();

        // Deposit enough to meet the minSum requirement and attempt collect,
        // which will fail due to the reverter callee, but it shouldn't affect MinSum.
        vm.deal(address(reverter), depositAmount);
        vm.prank(address(reverter));
        c.Deposit{value: depositAmount}();

        uint256 balanceBefore = c.balances(address(reverter));

        // Attempt to collect, which will fail because Log.AddMessage calls back to the reverter which reverts
        // Use try/catch to handle the revert
        vm.prank(address(reverter));
        try c.Collect(collectAmount) {
            // Should not reach here
        } catch {
            // Expected revert
        }

        // The invariant: MinSum should still equal the value set in the last successful SetMinSum call
        assertTrue(c.MinSum() == minSumAfterSet);
    }
}

