pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.Initialized();
        c.SetMinSum(10);
    }

    function testFuzz_property(uint256 depositAmt, uint256 collectAmt) public {
        // Admissible domain: keep sums reasonable to avoid overflows and ensure actor has funds
        vm.assume(depositAmt <= type(uint128).max);
        vm.assume(collectAmt <= type(uint128).max);
        vm.assume(depositAmt > 0);
        vm.assume(collectAmt > 0);

        // Deploy adversarial callee that always reverts on receiving ether
        Reverter reverter = new Reverter();
        address actor = address(reverter);

        // Fund the actor and deposit into C
        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.Deposit{value: depositAmt}();

        // Record balance before collect
        uint256 balanceBefore = c.balances(actor);

        // Attempt collect, track whether it reverted
        bool ok;
        vm.prank(actor);
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // Read final balance (only meaningful if no revert and collectAmt was deducted)
        uint256 balanceAfter = c.balances(actor);

        // GENERAL RULE the reference satisfies for ALL inputs:
        // If C reverts because the external callee fails (here always), the balance stays unchanged.
        // If it does NOT revert, the balance MUST have decreased by exactly collectAmt.
        // Because the buggy version changes the guard on MinSum, the set of inputs where it reverts differs,
        // causing a violation of this claim.
        if (ok) {
            assertEq(balanceAfter, balanceBefore - collectAmt);
        } else {
            assertEq(balanceAfter, balanceBefore);
        }
    }
}

